INSERT INTO `tbl_faq` VALUES (1,'ewd','ewd','c4ca4238a0b923820dcc509a6f75849b','<p>ewddewd</p>',NULL,1,'2026-06-05 15:24:39','2026-06-23 20:40:12',NULL),(2,'ewdw','ewdw','c81e728d9d4c2f636f067f89cc14862c','<p>wed</p>',NULL,1,'2026-06-06 16:02:53','2026-06-23 20:40:38',NULL),(3,'ewd','ewd1','eccbc87e4b5ce2fe28308fd9f2a7baf3','<p>wedew</p>',NULL,1,'2026-06-06 16:02:57','2026-06-23 20:40:43',NULL),(4,'What curriculum does K.K. International School follow?','what-curriculum-does-kk-international-school-follow','a87ff679a2f3e71d9181a67b7542122c','<p>K.K. International School follows the <strong data-start=\"101\" data-end=\"146\">National Education Board (NEB) curriculum</strong>, providing a well-structured academic program that emphasizes conceptual understanding, critical thinking, creativity, and practical learning. Our curriculum is designed to nurture students academically, socially, and emotionally, while preparing them with the knowledge, skills, and values needed to succeed in higher education and beyond.</p>',NULL,0,'2026-06-24 08:20:34','2026-06-24 08:20:34',NULL),(5,'When does the admission process begin?','when-does-the-admission-process-begin','e4da3b7fbbce2345d7772b0674a318d5','<p><div aria-hidden=\"true\" class=\"pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]\"></div></p><div class=\"qMYqUG_convSearchResultHighlightRoot\"><div class=\"\" data-turn-id-container=\"request-WEB:70cf8fd0-fa97-4832-ae2f-c4665472767f-25\" data-is-intersecting=\"true\"><section class=\"text-token-text-primary w-full focus:outline-none has-data-writing-block:pointer-events-none [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:70cf8fd0-fa97-4832-ae2f-c4665472767f-25\" data-turn-id-container=\"request-WEB:70cf8fd0-fa97-4832-ae2f-c4665472767f-25\" data-testid=\"conversation-turn-6\" data-turn=\"assistant\"><div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\"><div data-conversation-screenshot-content=\"\" class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\"><div class=\"flex max-w-full flex-col gap-4 grow\"><div data-message-author-role=\"assistant\" data-message-id=\"04b1e335-a455-4f56-b4dd-b1946c101d6f\" dir=\"auto\" data-message-model-slug=\"gpt-5-5\" class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" data-turn-start-message=\"true\" tabindex=\"0\"><div class=\"flex w-full flex-col gap-1 empty:hidden\"><div class=\"markdown prose dark:prose-invert wrap-break-word w-full light markdown-new-styling\"><p data-start=\"0\" data-end=\"162\" data-is-last-node=\"\" data-is-only-node=\"\"><span data-start=\"0\" data-end=\"162\" data-is-last-node=\"\" data-is-only-node=\"\">Admissions generally begin in February for the Pre-Primary section and in March for Classes 1 onwards. Applications are accepted subject to seat availability.</span></p></div></div></div></div><div class=\"z-0 flex min-h-[46px] justify-start\"></div><div class=\"mt-3 w-full empty:hidden\"><div class=\"text-center\"></div></div></div></div></section></div></div>',NULL,0,'2026-06-24 08:23:05','2026-06-24 08:23:05',NULL),(6,'What documents are required for admission?','what-documents-are-required-for-admission','1679091c5a880faf6fb5e6087eb1b2dc','<p data-start=\"1054\" data-end=\"1152\">Typically, the following documents are required:</p><p>\r\n</p><ul data-start=\"1153\" data-end=\"1318\">\r\n<li data-section-id=\"1b734u0\" data-start=\"1153\" data-end=\"1172\">\r\nBirth Certificate\r\n</li>\r\n<li data-section-id=\"1l7xjxz\" data-start=\"1173\" data-end=\"1202\">\r\nPrevious School Report Card\r\n</li>\r\n<li data-section-id=\"ujn6yd\" data-start=\"1203\" data-end=\"1241\">\r\nTransfer Certificate&nbsp;</li>\r\n<li data-section-id=\"1tq1vi3\" data-start=\"1242\" data-end=\"1269\">\r\nPassport-size photographs</li>\r\n<li data-section-id=\"1nw1e71\" data-start=\"1301\" data-end=\"1318\">\r\nParent ID Proof</li></ul>',NULL,0,'2026-06-24 08:24:22','2026-06-24 08:24:22',NULL),(7,'Is there an entrance test?','is-there-an-entrance-test','8f14e45fceea167a5a36dedd4bea2543','<p>Depending on the grade, students may be required to appear for an assessment or interaction.</p>',NULL,0,'2026-06-24 08:24:49','2026-09-09 13:53:44',1),(8,'What teaching methodology does the school follow?','what-teaching-methodology-does-the-school-follow','c9f0f895fb98ab9159f51fd0297e236d','<p>We use activity-based, experiential, and technology-enabled learning that encourages conceptual understanding and problem-solving.</p>',NULL,0,'2026-06-24 08:25:43','2026-06-24 08:25:43',NULL),(9,'How can parents communicate with teachers?','how-can-parents-communicate-with-teachers','45c48cce2e2d7fbdea1afc51c7c6ad26','<p>Parents can communicate through parent-teacher meetings or by scheduling appointments.</p>',NULL,0,'2026-06-24 08:26:47','2026-06-24 08:26:47',NULL),(10,'How can I schedule a campus visit?','how-can-i-schedule-a-campus-visit','d3d9446802a44259755d38e6d163e820','<p>You can schedule a campus tour by contacting the admissions office at 025-525300 or filling out the enquiry form on our website.</p>',NULL,0,'2026-06-24 08:27:47','2026-06-24 08:27:47',NULL);
/*!40000 ALTER TABLE `tbl_faq` ENABLE KEYS */;
UNLOCK TABLES;

