INSERT INTO `tbl_testimonial` VALUES (1,NULL,'Tanka Bdr. Karki','c4ca4238a0b923820dcc509a6f75849b','tanka-bdr-karki','5','The school\'s modern teaching methods, caring faculty, and excellent communication with parents make KK International School an outstanding choice for quality education.',NULL,'202510231719twinbro.jpg',0,'2025-10-23 17:19:05','2026-06-09 21:32:23',NULL,NULL,NULL),(2,NULL,'Sushmita Rai','c81e728d9d4c2f636f067f89cc14862c','sushmita-rai','5','We are impressed by the school\'s focus on both education and character development. Our child looks forward to going to school every day and has gained confidence in many areas.',NULL,'202510231752twinbro.jpg',0,'2025-10-23 17:52:26','2026-06-09 21:31:39',NULL,NULL,NULL),(3,NULL,'Nirmal Magar','eccbc87e4b5ce2fe28308fd9f2a7baf3','nirmal-magar','5','K.K. International School has provided a nurturing environment where my child has grown academically and personally. The teachers are supportive, dedicated, and truly care about every student.',NULL,'202510231753twinbro.jpg',0,'2025-10-23 17:53:11','2026-06-09 21:33:29',NULL,NULL,NULL);
/*!40000 ALTER TABLE `tbl_testimonial` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `tbl_transfer_certificate`
--

DROP TABLE IF EXISTS `tbl_transfer_certificate`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tbl_transfer_certificate` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `serial_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `admission_no` varchar(100) DEFAULT NULL,
  `iemis_no` varchar(100) DEFAULT NULL,
  `student_name` varchar(255) DEFAULT NULL,
  `father_name` varchar(255) DEFAULT NULL,
  `mother_name` varchar(255) DEFAULT NULL,
  `admission_date_bs` varchar(20) DEFAULT NULL,
  `admission_date_ad` date DEFAULT NULL,
  `dob_bs` varchar(20) DEFAULT NULL,
  `dob_ad` date DEFAULT NULL,
  `last_grade` varchar(50) DEFAULT NULL,
  `is_promoted` varchar(10) DEFAULT NULL,
  `promoted_grade` varchar(50) DEFAULT NULL,
  `dues_paid` varchar(10) DEFAULT NULL,
  `eca` text DEFAULT NULL,
  `general_character` varchar(100) DEFAULT NULL,
  `reason` text DEFAULT NULL,
  `issue_date_bs` varchar(20) DEFAULT NULL,
  `issue_date_ad` date DEFAULT NULL,
  `principal_name` varchar(255) DEFAULT NULL,
  `signature_text` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
